MENU = {"chai": 20, "samosa": 15, "vada pav": 25}

def price_of(item):
    return MENU[item]

def order_total(order_text):
    # order_text looks like "chai x2, samosa x3"
    total = 0
    for part in order_text.split(","):
        name, qty = part.split(" x")
        total += price_of(name.strip()) * int(qty)
    return total

print(order_total("chai x2, samosa x3"))

