import logging
import sys

logging.basicConfig(stream=sys.stdout, level=logging.INFO, force=True,
                    format="%(levelname)s %(name)s: %(message)s")
log = logging.getLogger("importer")

def parse_amount(text):
    return int(text.replace(",", ""))

total = 0
for row in ["450", "1,200", "abc"]:
    try:
        total += parse_amount(row)
    except ValueError:
        log.exception("skipping bad row %r", row)
log.info("total imported: %d", total)

def parse_price(text):
    return float(text.replace("Rs", "").strip())

rows = ["Rs 450", "Rs 1200", "Rs 99.50", "Rs 1,250", "Rs 30"]

for i, row in enumerate(rows):
    try:
        parse_price(row)
    except ValueError as e:
        print(f"row {i} fails: {row!r} -> {e}")
